import{_ as a,c as e,o as d,b0 as x}from"./chunks/framework.BWMBvyU7.js";const p=JSON.parse('{"title":"LV015-编码","description":null,"frontmatter":{"title":"LV015-编码","date":"2025-12-14T20:31:43.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/data-type/126b1a6dc907282ed64973c3","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-14T20:31:43.642Z","fulluuid":"ed64973c36c8419486d8b1ee3f322062","useduuid":"ed64973c3"}},"headers":[],"relativePath":"sdoc/Language/c/data-type/126b1a6dc907282ed64973c3.md","filePath":"sdoc/01-编程语言/01-C语言/05-数据类型/LV015-编码.md","lastUpdated":1767431239000}'),n={name:"sdoc/Language/c/data-type/126b1a6dc907282ed64973c3.md"};function i(l,t,r,o,c,h){return d(),e("div",null,[...t[0]||(t[0]=[x('<h1 id="lv015-编码" tabindex="-1">LV015-编码 <a class="header-anchor" href="#lv015-编码" aria-label="Permalink to &quot;LV015-编码&quot;">​</a></h1><h2 id="一、源文件编码" tabindex="-1">一、源文件编码 <a class="header-anchor" href="#一、源文件编码" aria-label="Permalink to &quot;一、源文件编码&quot;">​</a></h2><p>上边了解了 C 语言中字符的编码，源文件也是存储在计算机中的，那源文件是什么编码呢？源文件最终会被存储到本地硬盘，或者远程服务器，这个时候就要尽量压缩文件体积，以节省硬盘空间或者网络流量，而代码中大部分的字符都是 ASCII 编码中的字符，用一个字节足以容纳，所以 UTF-8 编码是一个不错的选择。</p><p>UTF-8 兼容 ASCII ，并且 UTF-8 基于 Unicode ，支持全世界的字符。常见的 IDE 或者编辑器，例如 Xcode 、 Gedit 、 Vim 等，在创建源文件时一般也默认使用 UTF-8 编码。</p><p>还有一种是本地编码，所谓本地编码就是像 GBK 、 Big5 、 Shift-JIS 等这样的国家编码（地区编码）；针对不同国家发行的操作系统，默认的本地编码一般不同。简体中文版本的 Windows 默认的本地编码是 GBK 。 Visual Studio 就默认使用本地编码来创建源文件。</p><p>对于编译器来说，它往往支持多种编码格式的源文件。微软编译器、 GCC 、 LLVM/Clang （内嵌于 Xcode 中）都支持 UTF-8 和本地编码的源文件，微软编译器还支持 UTF-16 编码的源文件。如果考虑到源文件的通用性，就只能使用 UTF-8 和本地编码了。</p><h2 id="二、常见编码方式" tabindex="-1">二、常见编码方式 <a class="header-anchor" href="#二、常见编码方式" aria-label="Permalink to &quot;二、常见编码方式&quot;">​</a></h2><h3 id="_1-ascii-码" tabindex="-1">1. ASCII 码 <a class="header-anchor" href="#_1-ascii-码" aria-label="Permalink to &quot;1. ASCII 码&quot;">​</a></h3><p>前边介绍过了，它总共有 128 个，主要是用于窄字符的编码。</p><h3 id="_2-iso-8859-1" tabindex="-1">2. ISO-8859-1 <a class="header-anchor" href="#_2-iso-8859-1" aria-label="Permalink to &quot;2. ISO-8859-1&quot;">​</a></h3><p>ISO 组织在 ASCII 码基础上制定了一些列标准用来扩展 ASCII 编码，它们是 ISO-8859-1~ISO-8859-15 ，其中 ISO-8859-1 涵盖了大多数西欧语言字符，所有应用的最广泛。 ISO-8859-1 仍然是单字节编码，它总共能表示 256 个字符。</p><h3 id="_3-gb2312" tabindex="-1">3. GB2312 <a class="header-anchor" href="#_3-gb2312" aria-label="Permalink to &quot;3. GB2312&quot;">​</a></h3><p>全称是《信息交换用汉字编码字符集 基本集》，它是 <strong>双字节编码</strong>，总的编码范围是 A1-F7 ，其中从 A1-A9 是符号区，总共包含 682 个符号，从 B0-F7 是汉字区，包含 6763 个汉字。</p><h3 id="_4-gbk" tabindex="-1">4. GBK <a class="header-anchor" href="#_4-gbk" aria-label="Permalink to &quot;4. GBK&quot;">​</a></h3><p>全称叫《汉字内码扩展规范》，是国家技术监督局为 windows95 所制定的新的汉字内码规范，它的出现是为了扩展 GB2312 ，加入更多的汉字。</p><p>它的编码范围是 8140~FEFE （去掉 XX7F ）总共有 23940 个码位，它能表示 21003 个汉字，它的编码是和 GB2312 兼容的。</p><h3 id="_5-gb18030" tabindex="-1">5. GB18030 <a class="header-anchor" href="#_5-gb18030" aria-label="Permalink to &quot;5. GB18030&quot;">​</a></h3><p>全称是《信息交换用汉字编码字符集》，是我国的强制标准，它可能是单字节、双字节或者四字节编码，它的编码与 GB2312 编码兼容。</p><h3 id="_6-unicode-字符集" tabindex="-1">6. Unicode 字符集 <a class="header-anchor" href="#_6-unicode-字符集" aria-label="Permalink to &quot;6. Unicode 字符集&quot;">​</a></h3><p>前边也大致介绍了一下，这与 ASCII 很类似， Unicode 相当于一本很厚的字典，记录着世界上所有字符对应的一个数字。</p><p>它 <strong>仅仅只是一个字符集</strong>，规定了符合对应的二进制代码，至于这个二进制代码如何存储则没有任何规定。</p><h3 id="_7-utf-16" tabindex="-1">7. UTF-16 <a class="header-anchor" href="#_7-utf-16" aria-label="Permalink to &quot;7. UTF-16&quot;">​</a></h3><p>UTF-16 具体定义了 Unicode 字符在计算机中存取方法。 UTF-16 用两个字节来表示 Unicode 转化格式，这个是定长的表示方法，不论什么字符都可以用两个字节表示，两个字节是 16 个 bit ，所以叫 UTF-16 。</p><p>UTF-16 表示字符非常方便，每两个字节表示一个字符，这样在字符串操作时就大大简化了操作。</p><h3 id="_8-utf-8" tabindex="-1">8. UTF-8 <a class="header-anchor" href="#_8-utf-8" aria-label="Permalink to &quot;8. UTF-8&quot;">​</a></h3><p>UTF-16 统一采用两个字节表示一个字符，虽然在表示上非常简单方便，但是有很大一部分字符用一个字节就可以表示的现，这样存储空间放大了一倍，珍贵的内存空间就被浪费掉了。</p><p>UTF-8 全称 8bit Unicode Transformation Format ， 8 比特的 Unicode 通用转换格式。它采用了一种变长技术, 每个编码区域有不同的字码长度。不同类型的字符可以是由 1~6 个字节组成。 编码规则如下：</p><ul><li><p>对于单字节的符号, 字节的第一位（最高位，也就是第 8 位）设为 0 , 后面 7 位为这个符号的 unicode 码. 因此对于英语字母, 来说， UTF-8 编码和 ASCII 码是相同的.</p></li><li><p>对于 n 字节的符号( n &gt; 1 ), 第一个字节的前 n 位都设为 1 ，第 n+1 位设为 0 ，后面剩余的 n - 1 个字节的前两位一律设为 10 。剩下的二进制位, 全部为这个符号的 Unicode 码.</p></li></ul><table><tbody><tr><td align="center"> n </td> <td align="center" width="210px"> Unicode 十六进制码范围 </td> <td align="center"> UTF-8 二进制 </td></tr><tr><td align="center"> 1 </td> <td align="center" width="210px"> 0000 0000 - 0000 007F </td> <td align="left"> 0xxxxxxx </td></tr><tr><td align="center"> 2 </td> <td align="center" width="210px"> 0000 0080 - 0000 07FF </td> <td align="left"> 110xxxxx 10xxxxxx </td></tr><tr><td align="center"> 3 </td> <td align="center" width="210px"> 0000 0800 - 0000 FFFF </td> <td align="left"> 1110xxxx 10xxxxxx 10xxxxxx </td></tr><tr><td align="center"> 4 </td> <td align="center" width="210px"> 0001 0000 - 0010 FFFF </td> <td align="left"> 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx </td></tr><tr><td align="center"> 5 </td> <td align="center" width="210px"> 0020 0000 - 03FF FFFF </td> <td align="left"> 111110xx 10xxxxxx 10xxxxxx 10xxxxxx 10xxxxxx </td></tr><tr><td align="center"> 6 </td> <td align="center" width="210px"> 0400 0000 - 7FFF FFFF </td> <td align="left"> 1111110x 10xxxxxx 10xxxxxx 10xxxxxx 10xxxxxx 10xxxxxx </td></tr></tbody></table> 【注意】在 UTF-8 编码中，英文字符占一个字节，中文字符占用 3 个字节。 ',30)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
